package com.metabuild.schema.platform;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class Task20PlatformMigrationContractTest {@Test void ownsDictionaryCompanyAndProfileTablesWithDatabaseInvariants() throws Exception {String sql=Files.readString(Path.of("src/main/resources/db/migration/platform/V10__add_admin_dictionary_company_profile.sql"));for(String table:new String[]{"mb_dictionary","mb_dictionary_item","mb_company","mb_user_profile"})assertTrue(sql.contains("create table "+table+" ("),table);assertTrue(sql.contains("constraint mb_dictionary_code_unique unique (code)"));assertTrue(sql.contains("constraint mb_dictionary_item_value_unique unique (dictionary_id,value)"));assertTrue(sql.contains("references mb_dictionary(id) on delete cascade"));assertTrue(sql.contains("references mb_user(id) on delete cascade"));assertTrue(sql.contains("color in ('primary','success','warning','danger','neutral')"));assertFalse(sql.contains("gen_random_uuid"));assertFalse(sql.contains("uuid_generate_v4"));}}
